<script>
const stepupText=<?=json_encode($stepupText,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE)?>;
let csrf=<?=json_encode(oneid_csrf_token())?>, purpose=<?=json_encode($purpose)?>, setupMode=<?=json_encode($setupMode)?>, enrollmentIntent=<?=json_encode($enrollmentIntent)?>, resetIntent=<?=json_encode($resetIntent)?>, successRedirect=<?=json_encode($successRedirect)?>, state={}; const api=<?=json_encode(APP_URL.'/lib/q_func.php')?>;
const messageBox=document.getElementById('message'),statusBox=document.getElementById('status'),setupBox=document.getElementById('setup'),resetBox=document.getElementById('reset'),resetReason=document.getElementById('resetReason'),bootstrapBox=document.getElementById('bootstrap'),challengeBox=document.getElementById('challengeBox'),disabledNotice=document.getElementById('disabledNotice');
function technicalError(e,labels={}){const code=String(e&&e.code||'').trim(),reference=String(e&&e.correlation_id||'').trim();let message=labels[code]||String(e&&e.error||'').trim()||stepupText.request_failed;if(code)message+=' ['+code+']';if(reference)message+=' — '+stepupText.technical_reference+': '+reference;return message}
function msg(t,ok=false){messageBox.innerHTML='<div class="msg '+(ok?'ok':'bad')+'"></div>';messageBox.firstChild.textContent=t||stepupText.request_failed}
async function post(action,data={}){let r=await fetch(api,{method:'POST',headers:{'X-CSRF-Token':csrf,'Accept':'application/json'},body:new URLSearchParams({_csrf_token:csrf,[action]:'1',...data})});let j=await r.json();if(!r.ok||j.status===0)throw j;if(j.csrf_token)csrf=j.csrf_token;return j}
function bindCodeEnter(input,button){input.setAttribute('aria-keyshortcuts','Enter');input.addEventListener('keydown',event=>{if(event.key!=='Enter'||event.isComposing||event.repeat)return;event.preventDefault();if(!button.disabled)button.click()})}
async function load(){try{state=await post('admin_step_up_status',{purpose});if(state.grant_valid&&!setupMode){location.replace(successRedirect);return}statusBox.textContent=`Feature: ${state.feature_enabled?stepupText.active:stepupText.inactive} | E-mail: ${state.masked_email||stepupText.none} | Authenticator: ${state.totp_available?stepupText.active:stepupText.not_registered}`;authFactorTotp.disabled=!state.totp_available;authFactorEmail.disabled=!state.email_available;authFactor.value=resetIntent?'EMAIL_OTP':(state.preferred_factor==='TOTP'&&state.totp_available?'TOTP':'EMAIL_OTP');authFactor.disabled=false;chooseFactor.disabled=false;chooseFactor.textContent=stepupText.continue;const emailOnly=resetIntent||(!state.totp_available&&state.email_available);factorChoice.style.display=emailOnly?'none':'block';if(emailOnly){totpBox.classList.add('hidden');emailBox.classList.remove('hidden');emailHint.textContent=stepupText.email_will_send+' '+(state.masked_email||stepupText.official_email);factorIntro.textContent=resetIntent?stepupText.email_only_reset:(purpose==='SECURITY_CONFIGURATION_CHANGE'?stepupText.email_only_enroll:stepupText.email_only_access)}else{factorIntro.textContent=stepupText.method_intro}setupBox.style.display=!resetIntent&&!state.totp_available&&(!state.feature_enabled||setupMode)?'block':'none';resetBox.classList.toggle('hidden',!(setupMode&&resetIntent&&state.totp_available));bootstrapBox.style.display=state.feature_enabled?'none':'block';challengeBox.style.display=state.feature_enabled&&!setupMode?'block':'none';disabledNotice.classList.toggle('hidden',state.feature_enabled);if(setupMode&&!state.totp_available){msg(stepupText.security_verified_enroll,true)}if(setupMode&&resetIntent&&state.totp_available){msg(stepupText.email_verified_reset,true)}}catch(e){authFactor.disabled=true;chooseFactor.disabled=true;chooseFactor.textContent=stepupText.unavailable;msg(technicalError(e))}}
document.getElementById('chooseFactor').onclick=()=>{emailBox.classList.add('hidden');totpBox.classList.add('hidden');if(authFactor.value==='TOTP'){if(!state.totp_available){msg(stepupText.authenticator_unavailable);return}totpBox.classList.remove('hidden')}else{emailHint.textContent=stepupText.email_will_send+' '+(state.masked_email||stepupText.official_email);emailBox.classList.remove('hidden')}};
let resendTimer=null;
function startResendCountdown(seconds){clearInterval(resendTimer);let remaining=Math.max(1,Number(seconds)||60);emailRequest.disabled=true;const tick=()=>{emailRequest.textContent=`${stepupText.resend} (${remaining}s)`;remaining--;if(remaining<0){clearInterval(resendTimer);resendTimer=null;emailRequest.disabled=false;emailRequest.textContent=stepupText.resend_email}};tick();resendTimer=setInterval(tick,1000)}
emailRequest.onclick=async()=>{try{emailRequest.disabled=true;emailRequest.textContent=stepupText.sending;let j=await post('admin_step_up_request_email',{purpose});challengeId.value=j.challenge_id;startResendCountdown(j.resend_after_seconds);msg(stepupText.email_sent+' '+j.masked_email+'. '+stepupText.check_mail,true)}catch(e){emailRequest.disabled=false;emailRequest.textContent=stepupText.email_send;if(e.code==='STEP_UP_RESEND_COOLDOWN'){startResendCountdown(60);msg(stepupText.cooldown)}else{msg(technicalError(e))}}};
emailVerify.onclick=async()=>{try{await post('admin_step_up_verify_email',{purpose,challenge_id:challengeId.value,code:emailCode.value});location.href=resetIntent?<?=json_encode(APP_URL.'/page/admin-step-up?purpose=SECURITY_CONFIGURATION_CHANGE&setup=totp&intent=totp_reset')?>:(!state.totp_available&&purpose==='SECURITY_CONFIGURATION_CHANGE'?<?=json_encode(APP_URL.'/page/admin-step-up?purpose=SECURITY_CONFIGURATION_CHANGE&setup=totp&intent=totp_enroll')?>:successRedirect)}catch(e){const labels={STEP_UP_VERIFICATION_FAILED:stepupText.otp_invalid,STEP_UP_EXPIRED:stepupText.otp_expired,STEP_UP_REPLAYED:stepupText.otp_replayed};msg(technicalError(e,labels))}};
totpVerify.onclick=async()=>{try{await post('admin_step_up_verify_totp',{purpose,code:totpCode.value});location.href=successRedirect}catch(e){msg(technicalError(e))}};
enroll.onclick=async()=>{try{let j=await post('admin_totp_enroll',{current_password:currentPassword.value,device_label:deviceLabel.value});factorId.value=j.factor_id;secret.textContent=j.secret;otpUri.href=j.provisioning_uri;qr.src='admin-totp-qr?factor_id='+encodeURIComponent(j.factor_id);provision.classList.remove('hidden');msg(stepupText.qr_generated,true)}catch(e){msg(technicalError(e))}};
document.getElementById('confirm').onclick=async()=>{try{await post('admin_totp_confirm',{factor_id:factorId.value,code:confirmCode.value});provision.classList.add('hidden');await load();msg(stepupText.authenticator_active,true)}catch(e){msg(technicalError(e))}};
document.getElementById('resetAuthenticator').onclick=()=>{let reason=resetReason.value.trim();if(reason.length<10){swal(stepupText.reason_required,stepupText.reason_minimum,'warning');return}swal({title:stepupText.reset_authenticator+'?',text:stepupText.revoke_intro,type:'warning',showCancelButton:true,confirmButtonColor:'#b4233b',confirmButtonText:stepupText.revoke_enroll,cancelButtonText:stepupText.cancel,closeOnConfirm:false},async function(){try{await post('admin_totp_revoke',{factor_id:state.totp_factor_id,reason});swal({title:stepupText.revoke_success,text:stepupText.revoke_next,type:'success',confirmButtonText:stepupText.continue,closeOnConfirm:false},function(){location.replace(<?=json_encode(APP_URL.'/page/admin-step-up?purpose=SECURITY_CONFIGURATION_CHANGE&setup=totp&intent=totp_enroll')?>)})}catch(e){swal(stepupText.reset_failed,technicalError(e)||stepupText.reset_request_failed,'error')}})};
document.getElementById('enable').onclick=async()=>{try{await post('admin_2fa_bootstrap_enable',{current_password:document.getElementById('bootstrapPassword').value,configuration_version:state.configuration_version,change_reason:document.getElementById('changeReason').value,change_id:document.getElementById('changeId').value,typed_confirmation:document.getElementById('typed').value});msg(stepupText.enabled,true);await load()}catch(e){msg(technicalError(e))}};
bindCodeEnter(emailCode,emailVerify);
bindCodeEnter(totpCode,totpVerify);
bindCodeEnter(confirmCode,document.getElementById('confirm'));
load();
</script></body></html>
